"""Reproduce typed form metadata from the supplied CSV; no external packages."""
import csv, json
from pathlib import Path
root = Path(__file__).resolve().parents[1]
with (root / 'data/application-fields-R01-R03.csv').open(encoding='utf-8-sig', newline='') as file:
    rows = list(csv.DictReader(file))
fields = [dict(product=r['Продукт'], number=int(r['№ поля']), code=r['Код поля'], label=r['Наименование поля'].strip(), requiredIP=r['Обязательно для ИП']=='Да', requiredOOO=r['Обязательно для ООО']=='Да', rule=r['Правило / формат'], source=r['Источник данных'], method=r['Способ заполнения'], dbField=r['Поле БД']) for r in rows]
target = root / 'src/domain/fields.ts'
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text("// Generated by scripts/generate-fields.py. Edit the CSV, then regenerate.\nimport type { Product } from './types';\nexport interface FieldDefinition { product:Product;number:number;code:string;label:string;requiredIP:boolean;requiredOOO:boolean;rule:string;source:string;method:string;dbField:string; }\nexport const fields: FieldDefinition[] = " + json.dumps(fields, ensure_ascii=False, indent=2) + ';\n', encoding='utf-8')
print(f'Generated {len(fields)} field definitions')
